package com.veyra.chat;
import com.veyra.auth.JwtService;import org.springframework.context.annotation.Configuration;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.messaging.*;import org.springframework.messaging.simp.stomp.StompCommand;import org.springframework.messaging.support.ChannelInterceptor;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.web.socket.config.annotation.*;
@Configuration public class StompAuthConfig implements WebSocketMessageBrokerConfigurer{private final JwtService jwt;private final JdbcTemplate db;public StompAuthConfig(JwtService j,JdbcTemplate d){jwt=j;db=d;}public void configureClientInboundChannel(org.springframework.messaging.simp.config.ChannelRegistration r){r.interceptors(new ChannelInterceptor(){public Message<?>preSend(Message<?>m,MessageChannel c){var a=org.springframework.messaging.simp.stomp.StompHeaderAccessor.wrap(m);if(StompCommand.CONNECT.equals(a.getCommand())){String h=a.getFirstNativeHeader("Authorization");if(h==null||!h.startsWith("Bearer "))throw new org.springframework.security.access.AccessDeniedException("JWT required");var u=jwt.userId(h.substring(7));var roles=db.queryForList("select r.code from roles r join user_roles ur on ur.role_id=r.id where ur.user_id=?",String.class,u).stream().map(x->new SimpleGrantedAuthority("ROLE_"+x)).toList();a.setUser(new UsernamePasswordAuthenticationToken(u,null,roles));}return m;}});}}
